import { Component, OnInit, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { RouterModule } from '@angular/router'; // Para os botões de navegação funcionarem
import { ScheduleService } from '../../core/services/schedule/schedule.service';

@Component({
    selector: 'app-agenda',
    standalone: true,
    imports: [CommonModule, FormsModule, RouterModule], // RouterModule adicionado para a navegação
    templateUrl: './schedule.component.html',
    styleUrls: ['./schedule.component.css']
})
export class AgendaComponent implements OnInit {
    private scheduleService = inject(ScheduleService);

    // Lista que vai armazenar os compromissos vindos do banco
    schedules: any[] = [];

    // Variáveis para o formulário de novo compromisso
    newScheduleTitle: string = '';
    newScheduleDate: string = '';

    ngOnInit(): void {
        this.loadSchedules();
    }

    // Busca os compromissos do usuário logado usando o GET do seu serviço
    loadSchedules(): void {
        this.scheduleService.getSchedulesByUser().subscribe({
            next: (res: any) => {
                this.schedules = Array.isArray(res) ? res : [];
            },
            error: (err) => console.error('Erro ao carregar a agenda:', err)
        });
    }

    // Cria um novo compromisso usando o POST do seu serviço
    addSchedule(): void {
        if (!this.newScheduleTitle.trim() || !this.newScheduleDate) {
            alert('Por favor, preencha o título e a data do compromisso.');
            return;
        }

        // Estrutura do ScheduleRequest (Ajuste os nomes se o seu modelo for diferente)
        const payload = {
            title: this.newScheduleTitle, // ou description: this.newScheduleTitle
            date: this.newScheduleDate,
            type: 'GERAL' // Exemplo: se o seu backend exige um "type" obrigatório
        };

        this.scheduleService.createSchedule(payload as any).subscribe({
            next: () => {
                // Limpa os campos do formulário após o sucesso
                this.newScheduleTitle = '';
                this.newScheduleDate = '';

                // Recarrega a lista para mostrar o novo compromisso
                this.loadSchedules();
            },
            error: (err) => {
                console.error('Erro ao adicionar compromisso:', err);
                alert('Falha ao salvar o compromisso.');
            }
        });
    }

    // Deleta um compromisso usando o DELETE do seu serviço
    deleteSchedule(id: number): void {
        if (confirm('Tem certeza que deseja excluir este compromisso?')) {
            this.scheduleService.deleteSchedule(id).subscribe({
                next: () => {
                    // Atualiza a lista após deletar
                    this.loadSchedules();
                },
                error: (err) => console.error('Erro ao deletar compromisso:', err)
            });
        }
    }
}
